// Actual Island II heightfield, generated offline from the measured Fitz Roy reference.
// Elevation data attribution and import provenance: ./provenance.json.
export const FLOW_SOURCE={size:257,worldSize:384,seed:"AERIE-647",min:-28.799999237060547,max:90.1510238647461,peakIndex:32260,step:0.0018150762661449094};
const encoded="";
let heights;
export function sourceHeights(){if(!heights){const raw=atob(encoded),view=new DataView(new ArrayBuffer(raw.length));for(let i=0;i<raw.length;i++)view.setUint8(i,raw.charCodeAt(i));heights=Float32Array.from({length:FLOW_SOURCE.size**2},(_,i)=>FLOW_SOURCE.min+view.getUint16(i*2,true)*FLOW_SOURCE.step);}return heights;}
export function sampleSource(u,v){const a=sourceHeights(),n=FLOW_SOURCE.size-1,x=Math.max(0,Math.min(n,u*n)),z=Math.max(0,Math.min(n,v*n)),x0=Math.floor(x),z0=Math.floor(z),x1=Math.min(n,x0+1),z1=Math.min(n,z0+1),tx=x-x0,tz=z-z0;return(a[z0*(n+1)+x0]*(1-tx)+a[z0*(n+1)+x1]*tx)*(1-tz)+(a[z1*(n+1)+x0]*(1-tx)+a[z1*(n+1)+x1]*tx)*tz;}
